// The scripted provider behind the queued-message rig: the adapter double the host drives, and
// the events it writes back as the provider would.

import { vi, type Mock } from 'vitest'
import type { StructuredAgentSessionHost } from './structured-agent-session-host'
import { startsWhenPublished } from './structured-agent-session-instant-start.test-support'
import { AGENT_JOURNAL_THREAD_SCOPE } from '../../../shared/agent-session-journal-types'
import { activeProviderContext } from '../../../shared/agent-session-provider-context'
import { codexProviderHandle } from '../../../shared/agent-session-provider-handle-encoding'
import type { AgentSessionRecordStore } from '../../runtime/agent-session-record-store'
import type { StructuredAgentSessionAdapter } from './structured-agent-session-adapter'
import type { StructuredAgentSessionEventSink } from './structured-agent-session-event-sink'
import {
  HOST_TEST_NOW as NOW,
  HOST_TEST_THREAD as THREAD
} from './structured-agent-session-host-test-data'

export type QueuedRigProviderOptions = {
  rewind?: NonNullable<StructuredAgentSessionAdapter['rewind']>
  recoverRewind?: NonNullable<StructuredAgentSessionAdapter['recoverRewind']>
  /** A child started for a chat whose chain already names a thread resumes it, so a chat whose
   *  child closed or died can start another. */
  restartable?: true
  /** Every child stays starting. */
  starting?: true
  /** The provider's Stop ends its child, as Claude's does. */
  stopEndsSession?: true
  /** Its child never answers its start, so it runs nothing it is handed. */
  startUnanswered?: true
  /** The model its child reports running; otherwise the agent's own `default`. */
  reportsModel?: string
  reportsEffort?: string
}

export function createQueuedRigProvider(
  store: Pick<AgentSessionRecordStore, 'getRecord'>,
  options: QueuedRigProviderOptions,
  host: () => StructuredAgentSessionHost
) {
  // Admitted: the message is written and unanswered, so the session owes work
  // until the test settles it.
  const dispatch: Mock<StructuredAgentSessionAdapter['dispatch']> = vi.fn(async () => ({
    state: 'admitted' as const
  }))
  // Every start the host asks for; one `holdNextStart` holds stays in its spawn until released.
  const starts: Mock<() => void> = vi.fn()
  let startHold: Promise<void> | null = null
  let startFailure: Error | null = null
  // The provider's receipt of a /compact; its end arrives later, as `finishCompact` writes it.
  const compact: Mock<NonNullable<StructuredAgentSessionAdapter['compact']>> = vi.fn(async () => ({
    state: 'accepted' as const,
    providerIdentity: null
  }))
  const cancelTurn: Mock<StructuredAgentSessionAdapter['cancelTurn']> = vi.fn(async () => ({
    cancelled: true
  }))
  const setOption: Mock<StructuredAgentSessionAdapter['setOption']> = vi.fn(async () => undefined)
  const closeSession: Mock<NonNullable<StructuredAgentSessionAdapter['closeSession']>> = vi.fn(
    async () => true
  )
  let events: StructuredAgentSessionEventSink | undefined
  let proveOpen: (() => void) | null = null

  const reported = () => ({
    model: options.reportsModel ?? 'default',
    ...(options.reportsEffort ? { effort: options.reportsEffort } : {})
  })
  const scripted: StructuredAgentSessionAdapter = {
    open: () =>
      options.starting
        ? new Promise((resolve) => {
            proveOpen = () => resolve({ reportedOptions: reported() })
          })
        : Promise.resolve({ reportedOptions: reported() }),
    acquire: async ({ identity, fence, spawnToken, events: sink }) => {
      starts()
      const hold = startHold
      startHold = null
      await hold
      const failure = startFailure
      startFailure = null
      if (failure) {
        throw failure
      }
      events = sink
      const record = store.getRecord(identity.sessionId)
      const context = record ? activeProviderContext(record) : null
      const resumes = options.restartable === true && context?.head != null
      const thread = context?.pendingClear
        ? `${THREAD}-context-${record!.providerContextBoundary!.operationId}`
        : (context?.head?.handle.nativeId ?? THREAD)
      return {
        process: {
          hostId: 'local',
          pid: 4242,
          processStartTimeMs: 1_700_000_000_000,
          spawnToken
        },
        acquisitionGeneration: 'generation-1',
        ...(options.starting ? { providerChildPhase: 'starting' as const } : {}),
        link: {
          linkId: `link-${fence}`,
          handle: codexProviderHandle(thread),
          origin: resumes ? ('resumed' as const) : ('created' as const),
          mintedAtFence: fence,
          observedAt: NOW
        }
      }
    },
    dispatch,
    closeSession,
    releaseAcquisition: vi.fn(async () => true),
    compact,
    cancelTurn,
    ...(options.stopEndsSession ? { stopEndsSession: () => true } : {}),
    ...(options.startUnanswered ? { startAnswered: () => false } : {}),
    answerPrompt: vi.fn(async ({ commit }) => commit()),
    setOption,
    ...(options.rewind
      ? { rewind: options.rewind, rewindSupport: () => ({ supported: true as const }) }
      : {}),
    ...(options.recoverRewind ? { recoverRewind: options.recoverRewind } : {})
  }

  const adapter = options.starting ? scripted : startsWhenPublished(scripted, host)

  /** What the provider's translator writes when a /compact's turn ends, as a success. */
  function finishCompact(): void {
    const { command } = compact.mock.calls.at(-1)![0]
    events!.appendLifecycleBatch!(
      `turn-completed:${command.clientMessageId}`,
      [
        {
          kind: 'item',
          identity: command.identity,
          body: { ...command.running, state: 'completed', outcome: 'success', completedAt: NOW },
          turnScope: AGENT_JOURNAL_THREAD_SCOPE
        }
      ],
      { lifecycle: true }
    )
  }

  /** Holds the next start in its spawn, with what it was asked for still queued, until released. */
  function holdNextStart(): () => void {
    let release = (): void => {}
    startHold = new Promise<void>((resolve) => (release = resolve))
    return () => release()
  }

  /** Fails the next start in its spawn, as an agent that cannot start does. */
  function failNextStart(error: Error): void {
    startFailure = error
  }

  /** The event sink the provider writes through. */
  function providerEvents(): StructuredAgentSessionEventSink {
    if (!events) {
      throw new Error('no provider bound')
    }
    return events
  }

  return {
    adapter,
    proveOpen: () => proveOpen?.(),
    dispatch,
    starts,
    holdNextStart,
    failNextStart,
    compact,
    cancelTurn,
    setOption,
    closeSession,
    finishCompact,
    providerEvents
  }
}

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import Database from '../../sqlite/sync-database'
import { OrchestrationDb } from './db'
import { SCHEMA_VERSION } from './db/contract-constants'
import { createRootDispatch } from './db/root-dispatch-test-fixture'
import { resolveOrchestrationMigrationStartVersion } from './orchestration-schema-version-skew'

const CREATOR_COLUMNS = ['creator_handle', 'creator_pane_key'] as const
const WORKER_PANE = 'tab_worker:dddddddd-dddd-4ddd-8ddd-dddddddddddd'

/** v37 records who created a Dispatch; a v36 row has no creator and must keep counting as a parent. */
describe('OrchestrationDb v36 to v37 migration', () => {
  let db: OrchestrationDb | undefined
  let tempDir: string | undefined

  afterEach(() => {
    db?.close()
    db = undefined
    if (tempDir) {
      rmSync(tempDir, { recursive: true, force: true })
      tempDir = undefined
    }
  })

  /** Builds a current database, then strips it back to the v36 shape it would have on disk. */
  function createV36Database(): { path: string; dispatchId: string } {
    tempDir = mkdtempSync(join(tmpdir(), 'orca-db-v37-'))
    const dbPath = join(tempDir, 'orchestration.db')
    const seed = new OrchestrationDb(dbPath)
    const run = seed.createRun({
      objective: 'pre-v37 run',
      coordinatorHandle: 'term_coord',
      coordinatorPaneKey: 'tab_coord:cccccccc-cccc-4ccc-8ccc-cccccccccccc'
    })
    const task = seed.createTask({ spec: 'dispatched before v37', runId: run.id })
    const dispatch = createRootDispatch(seed, task.id, 'term_worker', WORKER_PANE)
    seed.close()

    const raw = new Database(dbPath)
    for (const column of CREATOR_COLUMNS) {
      raw.exec(`ALTER TABLE dispatch_contexts DROP COLUMN ${column}`)
    }
    raw.pragma('user_version = 36')
    raw.close()
    return { path: dbPath, dispatchId: dispatch.id }
  }

  it('adds the columns as null and keeps the unattributed row a nesting parent', () => {
    const v36 = createV36Database()
    db = new OrchestrationDb(v36.path)

    expect(db.db.pragma('user_version', { simple: true })).toBe(SCHEMA_VERSION)
    expect(db.getDispatchContextById(v36.dispatchId)).toMatchObject({
      creator_handle: null,
      creator_pane_key: null
    })
    expect(
      db.resolveCreatorDepth({ kind: 'terminal', handle: 'term_worker', paneKey: WORKER_PANE })
    ).toBe(1)
  })

  it('repairs a database stamped v37 that never got the columns', () => {
    const v36 = createV36Database()
    const raw = new Database(v36.path)
    raw.pragma('user_version = 37')
    try {
      // Why: the skew repair is the only thing that catches a partially-written v37.
      expect(resolveOrchestrationMigrationStartVersion(raw, 37, SCHEMA_VERSION)).toBe(6)
    } finally {
      raw.close()
    }
  })
})

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import Database from '../../sqlite/sync-database'
import { OrchestrationDb } from './db'
import { SCHEMA_VERSION } from './db/contract-constants'

const DISPATCH_IDENTITY_COLUMNS = [
  'retry_of_dispatch_id',
  'creator_dispatch_id',
  'host_scope'
] as const

describe('R1 identity migration', () => {
  let db: OrchestrationDb | undefined
  let tempDir: string | undefined

  afterEach(() => {
    db?.close()
    if (tempDir) {
      rmSync(tempDir, { recursive: true, force: true })
    }
  })

  it('survives v30 to v31 to v30-writer to v31 without guessing provenance', () => {
    tempDir = mkdtempSync(join(tmpdir(), 'orca-r1-identity-'))
    const dbPath = join(tempDir, 'orchestration.db')
    db = new OrchestrationDb(dbPath)
    const task = db.createTask({ runId: 'run_legacy_local', spec: 'legacy supervised worker' })
    const started = db.createStartingWorkerDispatch({
      taskId: task.id,
      startOptions: { worktree: 'folder:/workspace' },
      runtimeEpoch: 'runtime-v30',
      creator: { kind: 'system' },
      maxDepth: Number.MAX_SAFE_INTEGER
    })
    db.prepareStartingWorkerAuthority({
      dispatchId: started.dispatch.id,
      handle: 'term_old',
      paneKey: 'tab_old:leaf_old',
      processIncarnation: 'pty_old:incarnation-old',
      worktreeId: 'folder:/workspace',
      hostScope: JSON.stringify({ kind: 'ssh', targetId: 'box-old' }),
      effects: [],
      setupState: 'not_applicable',
      terminalOwnership: 'created'
    })
    const resourceId = db.getWorkerTerminalResourceByOwner(started.dispatch.id)?.id
    db.close()
    db = undefined

    const v30 = new Database(dbPath)
    v30.exec(
      'DROP INDEX IF EXISTS idx_dispatch_retry_of; DROP INDEX IF EXISTS idx_dispatch_resource;'
    )
    for (const column of DISPATCH_IDENTITY_COLUMNS) {
      v30.exec(`ALTER TABLE dispatch_contexts DROP COLUMN ${column}`)
    }
    v30.exec('ALTER TABLE worker_terminal_resources DROP COLUMN endpoint_id')
    v30.exec('ALTER TABLE worker_terminal_resources DROP COLUMN endpoint_incarnation')
    v30.pragma('user_version = 30')
    v30.close()

    db = new OrchestrationDb(dbPath)
    expect(db.db.pragma('user_version', { simple: true })).toBe(SCHEMA_VERSION)
    expect(db.getDispatchContextById(started.dispatch.id)).toMatchObject({
      retry_of_dispatch_id: null,
      creator_dispatch_id: null,
      host_scope: null
    })
    // Re-added by v31 without guessing: a v30 writer never recorded endpoint identity.
    expect(db.getWorkerTerminalResource(resourceId!)).toMatchObject({
      endpoint_id: null,
      endpoint_incarnation: null
    })
    db.close()
    db = undefined

    const oldWriter = new Database(dbPath)
    oldWriter.pragma('user_version = 30')
    oldWriter.exec(`
      INSERT INTO tasks (id, spec, status) VALUES ('task_old_writer', 'old writer', 'dispatched');
      INSERT INTO dispatch_contexts (id, task_id, status)
        VALUES ('ctx_old_writer', 'task_old_writer', 'dispatched');
    `)
    oldWriter.close()

    db = new OrchestrationDb(dbPath)
    expect(db.db.pragma('user_version', { simple: true })).toBe(SCHEMA_VERSION)
    expect(db.getDispatchContextById('ctx_old_writer')).toMatchObject({
      creator_dispatch_id: null,
      host_scope: null
    })
  })

  it('drops the v31 identity columns no reader ever consumed', () => {
    tempDir = mkdtempSync(join(tmpdir(), 'orca-r1-identity-drop-'))
    const dbPath = join(tempDir, 'orchestration.db')
    db = new OrchestrationDb(dbPath)
    db.close()
    db = undefined

    const v34 = new Database(dbPath)
    for (const column of ['creator_role', 'endpoint_id'] as const) {
      v34.exec(`ALTER TABLE dispatch_contexts ADD COLUMN ${column} TEXT`)
    }
    for (const column of ['endpoint_incarnation', 'attachment_kind', 'resource_id'] as const) {
      v34.exec(`ALTER TABLE dispatch_contexts ADD COLUMN ${column} TEXT`)
    }
    v34.exec('CREATE INDEX idx_dispatch_resource ON dispatch_contexts(resource_id)')
    v34.pragma('user_version = 34')
    v34.close()

    db = new OrchestrationDb(dbPath)
    const columns = (db.db.pragma('table_info(dispatch_contexts)') as { name: string }[]).map(
      ({ name }) => name
    )
    expect(columns).toEqual(
      expect.arrayContaining(['retry_of_dispatch_id', 'creator_dispatch_id', 'host_scope', 'depth'])
    )
    expect(columns).not.toContain('creator_role')
    expect(columns).not.toContain('resource_id')
    expect(columns).not.toContain('attachment_kind')
    expect(
      db.db.prepare("SELECT name FROM sqlite_master WHERE name = 'idx_dispatch_resource'").get()
    ).toBeUndefined()
  })
})

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import Database from '../../../../sqlite/sync-database'
import { OrchestrationDb } from '../orchestration-db'
import { dropDerivedDeliverySchema } from './derived-delivery-test-fixture'
import { resolveOrchestrationMigrationStartVersion } from '../../orchestration-schema-version-skew'
import { createRootDispatch, reattachDispatchConsumer } from '../root-dispatch-test-fixture'
import { SCHEMA_VERSION } from '../contract-constants'

describe('derived delivery migration', () => {
  const connections: OrchestrationDb[] = []
  const directories: string[] = []
  afterEach(() => {
    for (const db of connections.splice(0)) {
      db.close()
    }
    for (const directory of directories.splice(0)) {
      rmSync(directory, { recursive: true, force: true })
    }
  })
  function open(path: string) {
    const db = new OrchestrationDb(path)
    connections.push(db)
    return db
  }
  function databasePath() {
    const directory = mkdtempSync(join(tmpdir(), 'orca-derived-delivery-'))
    directories.push(directory)
    return join(directory, 'orchestration.db')
  }

  it('preserves batch identity and terminal facts while removing a persisted wedge', () => {
    const path = databasePath()
    const original = open(path)
    const run = original.createRun({
      objective: 'upgrade',
      coordinatorHandle: 'coord',
      coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
    })
    const params = { runId: run.id, consumerGeneration: run.consumer_generation }
    const old = original.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'old'
    })
    const batch = original.getDeliveryRaw(original.getOrCreateRunDelivery(params)!.delivery.id)!
    const next = original.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'next'
    })
    connections.pop()!.close()
    const raw = new Database(path)
    dropDerivedDeliverySchema(raw)
    raw.prepare('UPDATE messages SET read = 1 WHERE id = ?').run(old.id)
    raw.exec(`
      INSERT INTO deliveries (id, run_id, mailbox_handle, consumer_generation, message_ids, status, created_at, acknowledged_at)
      VALUES ('history_ack', '${run.id}', 'run:${run.id}', 1, '[]', 'acknowledged', '2026-01-01 00:00:00', '2026-01-02 00:00:00'),
             ('history_fence', '${run.id}', 'run:${run.id}', 1, '[]', 'fenced', '2026-01-03 00:00:00', NULL);
    `)
    raw.pragma('user_version = 40')
    raw.close()
    const db = open(path)
    expect(db.getDeliveryRaw(batch.id)).toEqual(batch)
    expect(db.hasOutstandingRunDelivery(run.id)).toBe(false)
    expect(db.getDeliveryRaw('history_ack')).toMatchObject({
      acknowledged_at: '2026-01-02 00:00:00',
      status: 'acknowledged'
    })
    expect(db.getDeliveryRaw('history_fence')).toMatchObject({
      acknowledged_at: null,
      status: 'fenced'
    })
    expect(() => db.acknowledgeRunDelivery({ ...params, deliveryId: 'history_fence' })).toThrow(
      expect.objectContaining({ code: 'consumer_fenced' })
    )
    expect(db.getOrCreateRunDelivery(params)?.messages.map((message) => message.id)).toEqual([
      next.id
    ])
    expect(db.getDeliveryRaw(batch.id)?.acknowledged_at).toBeNull()
    expect(resolveOrchestrationMigrationStartVersion(db.db, SCHEMA_VERSION, SCHEMA_VERSION)).toBe(
      SCHEMA_VERSION
    )
    const reopened = open(path)
    expect(reopened.getOrCreateRunDelivery(params)?.messages.map((message) => message.id)).toEqual([
      next.id
    ])
  })

  it('enforces one active batch using the same derived view and permits history', () => {
    const db = open(':memory:')
    const run = db.createRun({
      objective: 'constraint',
      coordinatorHandle: 'coord',
      coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
    })
    const message = db.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'one'
    })
    const params = { runId: run.id, consumerGeneration: run.consumer_generation }
    const first = db.getDeliveryRaw(db.getOrCreateRunDelivery(params)!.delivery.id)!
    const insert = db.db.prepare(`INSERT INTO deliveries
      (id, run_id, mailbox_handle, consumer_generation, message_ids, acknowledged_at, status)
      VALUES (?, ?, ?, ?, ?, ?, ?)`)
    const values = [run.id, `run:${run.id}`, run.consumer_generation, JSON.stringify([message.id])]
    expect(() => insert.run('duplicate', ...values, null, 'outstanding')).toThrow(
      'Mailbox already has an outstanding delivery'
    )
    expect(() =>
      insert.run('ack_history', ...values, '2026-01-01 00:00:00', 'acknowledged')
    ).not.toThrow()
    expect(() => insert.run('fenced_history', ...values, null, 'fenced')).not.toThrow()
    db.markAsRead([message.id])
    expect(() => insert.run('consumed_history', ...values, null, 'outstanding')).not.toThrow()
    expect(db.getDeliveryRaw(first.id)).toEqual(first)
    expect(db.hasOutstandingRunDelivery(run.id)).toBe(false)
  })

  it('shares a single batch across connections and rejects replaced consumers after it is consumed', () => {
    const path = databasePath()
    const first = open(path)
    const run = first.createRun({
      objective: 'connections',
      coordinatorHandle: 'coord',
      coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
    })
    const params = { runId: run.id, consumerGeneration: run.consumer_generation }
    const message = first.insertMessage({
      runId: run.id,
      from: 'worker',
      to: `run:${run.id}`,
      subject: 'one'
    })
    const second = open(path)
    const batch = first.getOrCreateRunDelivery(params)!
    expect(second.getOrCreateRunDelivery(params)?.delivery.id).toBe(batch.delivery.id)
    second.markAsRead([message.id])
    const replacement = second.bindRun({
      runId: run.id,
      coordinatorHandle: 'replacement',
      coordinatorPaneKey: 'other:22222222-2222-4222-9222-222222222222'
    })!
    expect(first.getDeliveryRaw(batch.delivery.id)).toMatchObject({
      status: 'fenced',
      acknowledged_at: null
    })
    first.insertMessage({ runId: run.id, from: 'worker', to: `run:${run.id}`, subject: 'next' })
    expect(() => first.getOrCreateRunDelivery(params)).toThrow(
      expect.objectContaining({ code: 'consumer_fenced' })
    )
    expect(() =>
      first.acknowledgeRunDelivery({ ...params, deliveryId: batch.delivery.id })
    ).toThrow(expect.objectContaining({ code: 'consumer_fenced' }))
    expect(
      second.getOrCreateRunDelivery({
        ...params,
        consumerGeneration: replacement.consumer_generation
      })?.messages[0].subject
    ).toBe('next')
  })

  it.each(['dispatch', 'attachment'] as const)(
    'fences a stale %s consumer across connections even after its batch is read',
    (consumerSource) => {
      const path = databasePath()
      const db = open(path)
      const run = db.createRun({
        objective: 'worker connections',
        coordinatorHandle: 'coord',
        coordinatorPaneKey: 'tab:11111111-1111-4111-8111-111111111111'
      })
      const dispatchId =
        consumerSource === 'dispatch'
          ? createRootDispatch(db, db.createTask({ spec: 'work', runId: run.id }).id, 'worker').id
          : 'ctx_remote'
      if (consumerSource === 'attachment') {
        db.createRemoteDispatchAttachment({
          runId: run.id,
          dispatchId,
          taskId: 'task_remote',
          homePeerFingerprint: 'peer',
          runtimeEpoch: 'epoch',
          protocolVersion: 1,
          mutationReceipt: {
            callerFingerprint: 'peer',
            requestId: 'attach',
            method: 'orchestration.federationAttachStart',
            payloadHash: 'hash'
          }
        })
      }
      const mailboxHandle = `dispatch:${dispatchId}`
      const message = db.insertMessage({
        runId: run.id,
        from: 'coord',
        to: mailboxHandle,
        subject: 'old'
      })
      const params = { runId: run.id, mailboxHandle, consumerGeneration: 0, consumerSource }
      const batch = db.getOrCreateMailboxDelivery(params)!
      const peer = open(path)
      peer.markAsRead([message.id])
      const authority = {
        dispatchId,
        paneKey: 'other:22222222-2222-4222-9222-222222222222',
        processIncarnation: 'worker:2'
      }
      if (consumerSource === 'dispatch') {
        reattachDispatchConsumer(peer, authority)
      } else {
        peer.prepareRemoteAttachmentAuthority({
          ...authority,
          worktreeId: 'folder',
          terminalHandle: 'replacement',
          setupState: 'not_applicable',
          effects: []
        })
      }
      expect(db.getDeliveryRaw(batch.delivery.id)).toMatchObject({
        status: 'fenced',
        acknowledged_at: null
      })
      peer.insertMessage({ runId: run.id, from: 'coord', to: mailboxHandle, subject: 'next' })
      expect(() => db.getOrCreateMailboxDelivery(params)).toThrow(
        expect.objectContaining({ code: 'consumer_fenced' })
      )
      expect(() =>
        db.acknowledgeMailboxDelivery({ ...params, deliveryId: batch.delivery.id })
      ).toThrow(expect.objectContaining({ code: 'consumer_fenced' }))
      expect(
        peer.getOrCreateMailboxDelivery({ ...params, consumerGeneration: 1 })?.messages[0].subject
      ).toBe('next')
    }
  )

  it('keeps the pre-v41 column and index shape a downgraded binary reads', () => {
    const db = open(':memory:')
    expect(
      (db.db.pragma('table_info(deliveries)') as { name: string }[]).map((c) => c.name)
    ).toContain('status')
    const index = db.db
      .prepare("SELECT sql FROM sqlite_master WHERE name = 'idx_deliveries_one_outstanding'")
      .get() as { sql: string }
    expect(index.sql).not.toContain('UNIQUE')
    expect(index.sql).toContain("status = 'outstanding' AND mailbox_handle != ''")
    // Why: a v40 binary probes exactly these objects before trusting the stamp; nothing it needs is gone.
    expect(resolveOrchestrationMigrationStartVersion(db.db, SCHEMA_VERSION, 40)).toBe(
      SCHEMA_VERSION
    )
  })

  it('recreates a missing derived view on reopen without changing batch records', () => {
    const path = databasePath()
    const db = open(path)
    db.db.exec('DROP VIEW outstanding_deliveries')
    const reopened = open(path)
    expect(reopened.hasOutstandingMailboxDelivery('run:missing')).toBe(false)
    expect(
      resolveOrchestrationMigrationStartVersion(reopened.db, SCHEMA_VERSION, SCHEMA_VERSION)
    ).toBe(SCHEMA_VERSION)
  })
})

import type { OrchestrationDb } from '../orchestration-db'

// Tests that hand-edit the deliveries table must drop the derived objects first: SQLite refuses
// DROP COLUMN / RENAME while a trigger or view still references the table. Reopening recreates them.
export function dropDerivedDeliverySchema(db: OrchestrationDb['db']): void {
  db.exec(
    'DROP TRIGGER IF EXISTS trg_deliveries_one_outstanding; DROP VIEW IF EXISTS outstanding_deliveries;'
  )
}

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
