import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import { ORCHESTRATION_CONTRACT_VERSION } from '../../../../../shared/protocol-version'
import { OrchestrationDb } from '../orchestration-db'
import { SCHEMA_VERSION, federatedStubHomeRunId } from '../contract-constants'
import { migrateV40 } from './migrate-v40'
import { importFederatedControlMessage } from '../../federation-control-message'

describe('federated home Run migration', () => {
  let db: OrchestrationDb
  beforeEach(() => {
    db = new OrchestrationDb(':memory:')
  })
  afterEach(() => db.close())

  function importInstruction(target: OrchestrationDb, dispatchId: string, messageId: string): void {
    expect(
      importFederatedControlMessage(target, {
        dispatchId,
        messageId,
        payload: JSON.stringify({ from: 'home', subject: 'Instruction', body: '', type: 'status' })
      })
    ).toEqual({ imported: true, type: 'status' })
  }

  function attachWithoutRunId(target: OrchestrationDb, dispatchId: string, runId?: string): void {
    target.createRemoteDispatchAttachment({
      dispatchId,
      runId,
      taskId: `task_${dispatchId}`,
      homePeerFingerprint: 'home',
      protocolVersion: ORCHESTRATION_CONTRACT_VERSION,
      runtimeEpoch: 'epoch',
      mutationReceipt: {
        callerFingerprint: 'home',
        requestId: `request_${dispatchId}`,
        method: 'orchestration.federationAttachStart',
        payloadHash: `payload_${dispatchId}`
      }
    })
  }

  it('backfills a pre-upgrade attachment with a stub home Run that keeps its mailbox', () => {
    db.db.exec('ALTER TABLE remote_dispatch_attachments DROP COLUMN home_run_id')
    db.db.exec(`INSERT INTO remote_dispatch_attachments
      (dispatch_id, task_id, home_peer_fingerprint, runtime_epoch)
      VALUES ('ctx_old', 'task_old', 'home', 'epoch')`)
    migrateV40.call(db, 39)
    const stubRunId = federatedStubHomeRunId('ctx_old')
    expect(db.getRemoteDispatchAttachment('ctx_old')?.home_run_id).toBe(stubRunId)
    expect(db.getRunRaw(stubRunId)).toMatchObject({ home_database: 'remote', legacy: 0 })
    importInstruction(db, 'ctx_old', 'message_old')
    expect(db.getMessageById('message_old')?.run_id).toBe(stubRunId)
  })

  it('mints a stub home Run when a v1.4.198 coordinator attaches without a Run id', () => {
    attachWithoutRunId(db, 'ctx_legacy_home')
    const stubRunId = federatedStubHomeRunId('ctx_legacy_home')
    expect(db.getRemoteDispatchAttachment('ctx_legacy_home')?.home_run_id).toBe(stubRunId)
    importInstruction(db, 'ctx_legacy_home', 'message_legacy_home')
    expect(db.getMessageById('message_legacy_home')?.run_id).toBe(stubRunId)
  })

  it('rejects a whitespace-only Run id instead of minting a stub', () => {
    expect(() => attachWithoutRunId(db, 'ctx_blank', '   ')).toThrow('Missing Run ID')
    expect(db.getRemoteDispatchAttachment('ctx_blank')).toBeUndefined()
  })

  it('repairs rows a rolled-back v1.4.198 host inserted after user_version reached 40', () => {
    const dir = mkdtempSync(join(tmpdir(), 'orca-federated-home-run-'))
    const dbPath = join(dir, 'orchestration.db')
    try {
      const upgraded = new OrchestrationDb(dbPath)
      expect(upgraded.db.pragma('user_version', { simple: true })).toBe(SCHEMA_VERSION)
      // v1.4.198's insert shape: no home_run_id column, so the DEFAULT '' lands.
      upgraded.db.exec(`INSERT INTO remote_dispatch_attachments
        (dispatch_id, task_id, home_peer_fingerprint, runtime_epoch)
        VALUES ('ctx_rolled_back', 'task_rolled_back', 'home', 'epoch')`)
      expect(upgraded.getRemoteDispatchAttachment('ctx_rolled_back')?.home_run_id).toBe('')
      expect(() =>
        importFederatedControlMessage(upgraded, {
          dispatchId: 'ctx_rolled_back',
          messageId: 'message_refused',
          payload: JSON.stringify({ from: 'home', subject: 'x', body: '', type: 'status' })
        })
      ).toThrow(/Run not found/)
      upgraded.close()

      const reopened = new OrchestrationDb(dbPath)
      try {
        const stubRunId = federatedStubHomeRunId('ctx_rolled_back')
        expect(reopened.getRemoteDispatchAttachment('ctx_rolled_back')?.home_run_id).toBe(stubRunId)
        expect(reopened.getRunRaw(stubRunId)).toMatchObject({ home_database: 'remote', legacy: 0 })
        importInstruction(reopened, 'ctx_rolled_back', 'message_rolled_back')
        expect(reopened.getMessageById('message_rolled_back')?.run_id).toBe(stubRunId)
      } finally {
        reopened.close()
      }
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })
})

import { mkdtempSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import Database from '../../../../sqlite/sync-database'
import { afterEach, describe, expect, it } from 'vitest'
import { OrchestrationDb } from '../orchestration-db'
import { SCHEMA_VERSION } from '../contract-constants'

/**
 * A pre-v39 database: the narrow archive CHECK, stamped at 38 so ONLY v39 runs.
 *
 * Seeding lower would still pass while exercising the whole v13->v39 chain instead, which
 * would mask a broken rebuild. `createTables` supplies every other table before migration, so
 * a 38 stamp survives the completeness check and the migration start resolves to 38.
 */
function seedLegacyDatabase(path: string): void {
  const db = new Database(path)
  db.exec(`
    CREATE TABLE worker_terminal_archives (
      dispatch_id   TEXT PRIMARY KEY,
      resource_id   TEXT NOT NULL,
      kind          TEXT NOT NULL CHECK(kind IN ('transcript_pin', 'terminal_tail')),
      content       TEXT NOT NULL,
      created_at    TEXT NOT NULL DEFAULT (datetime('now'))
    );
    INSERT INTO worker_terminal_archives (dispatch_id, resource_id, kind, content, created_at)
      VALUES ('d_old', 'res_old', 'terminal_tail', '{"lines":["kept"]}', '2026-01-01 00:00:00');
  `)
  db.pragma('user_version = 38')
  db.close()
}

describe('structured pointer schema migration', () => {
  // Why a real temp dir and a teardown: `$TMPDIR` is unset on Windows CI, so the interpolated
  // `/tmp/...` opened as `SQLITE_CANTOPEN`, and nothing removed the file on the platforms where it
  // did open.
  const tempRoots: string[] = []

  afterEach(() => {
    while (tempRoots.length > 0) {
      rmSync(tempRoots.pop() as string, { recursive: true, force: true })
    }
  })

  it('admits the structured archive kind and keeps existing rows', () => {
    const root = mkdtempSync(join(tmpdir(), 'orca-structured-migration-'))
    tempRoots.push(root)
    const path = join(root, 'orchestration.db')
    seedLegacyDatabase(path)
    const db = new OrchestrationDb(path)
    try {
      expect(db.db.pragma('user_version', { simple: true })).toBe(SCHEMA_VERSION)
      const kept = db.db
        .prepare('SELECT content FROM worker_terminal_archives WHERE dispatch_id = ?')
        .get('d_old') as { content: string }
      expect(kept.content).toContain('kept')
      db.storeWorkerTerminalArchive({
        dispatchId: 'd_new',
        resourceId: 'res_new',
        kind: 'structured_journal',
        content: '{"version":1}'
      })
      expect(db.getWorkerTerminalArchive('d_new')?.kind).toBe('structured_journal')
    } finally {
      db.close()
    }
  })

  it('creates the structured pointer operation store', () => {
    const db = new OrchestrationDb(':memory:')
    try {
      expect(db.getStructuredPointerOperation('dispatch:d1')).toBeUndefined()
      db.putStructuredPointerOperation({
        mailbox_handle: 'dispatch:d1',
        session_id: 's1',
        operation_id: '1757030400000-0123456789abcdef0123456789abcdef',
        batch_fingerprint: 'fp',
        minted_at_ms: 1_757_030_400_000
      })
      expect(db.getStructuredPointerOperation('dispatch:d1')?.operation_id).toBe(
        '1757030400000-0123456789abcdef0123456789abcdef'
      )
      db.deleteStructuredPointerOperation('dispatch:d1')
      expect(db.getStructuredPointerOperation('dispatch:d1')).toBeUndefined()
    } finally {
      db.close()
    }
  })
})

import {
  chmodSync,
  mkdirSync,
  mkdtempSync,
  renameSync,
  rmSync,
  symlinkSync,
  writeFileSync
} from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { afterEach, describe, expect, it } from 'vitest'
import {
  hasAppImagePathEnvironment,
  resolveAppImageRuntimeIdentity
} from './appimage-runtime-identity'

const fixtureRoots: string[] = []

function appImageHeader(machine: number): Buffer {
  const header = Buffer.alloc(64)
  header.set([0x7f, 0x45, 0x4c, 0x46, 0x02, 0x01, 0x01])
  header.set([0x41, 0x49, 0x02], 8)
  header.writeUInt16LE(machine, 18)
  return header
}

function createFixture(appDirName = '.mount_Orca123', machine = 0x3e) {
  const root = mkdtempSync(join(tmpdir(), 'orca-appimage-identity-'))
  const appImagePath = join(root, 'Applications', 'Orca.AppImage')
  const appDirPath = join(root, appDirName)
  const execPath = join(appDirPath, 'orca-ide')
  const resourcesPath = join(appDirPath, 'resources')
  const packageTypePath = join(resourcesPath, 'package-type')
  const packageMarkerPath = join(resourcesPath, 'app.asar.unpacked', 'out', 'package.json')
  fixtureRoots.push(root)
  mkdirSync(dirname(appImagePath), { recursive: true })
  mkdirSync(dirname(packageMarkerPath), { recursive: true })
  writeFileSync(appImagePath, appImageHeader(machine), { mode: 0o755 })
  writeFileSync(join(appDirPath, 'AppRun'), '#!/bin/sh\n', { mode: 0o755 })
  writeFileSync(execPath, appImageHeader(machine), { mode: 0o755 })
  writeFileSync(
    packageMarkerPath,
    JSON.stringify({ name: 'orca-compiled-output', type: 'commonjs', private: true })
  )
  return {
    root,
    appImagePath,
    appDirPath,
    execPath,
    resourcesPath,
    packageTypePath,
    packageMarkerPath,
    identity: {
      platform: 'linux' as const,
      environment: { APPIMAGE: appImagePath, APPDIR: appDirPath },
      execPath,
      resourcesPath
    }
  }
}

afterEach(() => {
  for (const root of fixtureRoots.splice(0)) {
    rmSync(root, { recursive: true, force: true })
  }
})

describe.skipIf(process.platform === 'win32')('resolveAppImageRuntimeIdentity', () => {
  it.each([
    ['x64', 0x3e, '.mount_Orca123'],
    ['ARM64 extract-and-run', 0xb7, 'appimage_extracted_123']
  ])('accepts a complete %s AppImage runtime', (_architecture, machine, appDirName) => {
    const fixture = createFixture(appDirName, machine)
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toEqual({
      appImagePath: fixture.appImagePath
    })
  })

  it('accepts an AppImage moved independently of its runtime directory', () => {
    const fixture = createFixture()
    const movedPath = join(fixture.root, 'Moved Apps', 'Orca current.AppImage')
    mkdirSync(dirname(movedPath), { recursive: true })
    renameSync(fixture.appImagePath, movedPath)
    fixture.identity.environment.APPIMAGE = movedPath
    expect(resolveAppImageRuntimeIdentity(fixture.identity)?.appImagePath).toBe(movedPath)
  })

  it('accepts the exact AppImage package-type marker', () => {
    const fixture = createFixture()
    rmSync(fixture.packageMarkerPath)
    writeFileSync(fixture.packageTypePath, 'AppImage')
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).not.toBeNull()
  })

  it.each([
    ['APPIMAGE', undefined],
    ['APPIMAGE', 'relative/Orca.AppImage'],
    ['APPDIR', undefined],
    ['APPDIR', 'relative/mount'],
    ['APPIMAGE', '/tmp/Orca\0.AppImage']
  ] as const)('rejects an unusable %s value', (key, value) => {
    const fixture = createFixture()
    expect(
      resolveAppImageRuntimeIdentity({
        ...fixture.identity,
        environment: { ...fixture.identity.environment, [key]: value }
      })
    ).toBeNull()
  })

  it.each([
    ['an ordinary executable', (path: string) => writeFileSync(path, '#!/bin/sh\n')],
    [
      'bad ELF magic',
      (path: string) => {
        const header = appImageHeader(0x3e)
        header[0] = 0
        writeFileSync(path, header)
      }
    ],
    [
      'bad AppImage type magic',
      (path: string) => {
        const header = appImageHeader(0x3e)
        header[10] = 1
        writeFileSync(path, header)
      }
    ],
    ['a non-executable file', (path: string) => chmodSync(path, 0o644)],
    [
      'a directory',
      (path: string) => {
        rmSync(path)
        mkdirSync(path)
      }
    ]
  ])('rejects APPIMAGE pointing to %s', (_case, mutate) => {
    const fixture = createFixture()
    mutate(fixture.appImagePath)
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it.each([
    [
      'AppRun',
      (fixture: ReturnType<typeof createFixture>) => rmSync(join(fixture.appDirPath, 'AppRun'))
    ],
    [
      'an executable AppRun',
      (fixture: ReturnType<typeof createFixture>) =>
        chmodSync(join(fixture.appDirPath, 'AppRun'), 0o644)
    ],
    [
      'the Orca package marker',
      (fixture: ReturnType<typeof createFixture>) => rmSync(fixture.packageMarkerPath)
    ]
  ])('rejects a runtime missing %s', (_case, mutate) => {
    const fixture = createFixture()
    mutate(fixture)
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it('rejects a package marker for a different application', () => {
    const fixture = createFixture()
    writeFileSync(
      fixture.packageMarkerPath,
      JSON.stringify({ name: 'foreign-compiled-output', type: 'commonjs' })
    )
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it('rejects an inexact package-type marker without the Orca fallback', () => {
    const fixture = createFixture()
    rmSync(fixture.packageMarkerPath)
    writeFileSync(fixture.packageTypePath, 'appimage')
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it('rejects payload evidence that resolves outside APPDIR', () => {
    const fixture = createFixture()
    const externalAppRun = join(fixture.root, 'foreign-AppRun')
    writeFileSync(externalAppRun, '#!/bin/sh\n', { mode: 0o755 })
    rmSync(join(fixture.appDirPath, 'AppRun'))
    symlinkSync(externalAppRun, join(fixture.appDirPath, 'AppRun'))
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it('rejects a package marker that resolves outside APPDIR', () => {
    const fixture = createFixture()
    const externalMarker = join(fixture.root, 'foreign-package.json')
    writeFileSync(
      externalMarker,
      JSON.stringify({ name: 'orca-compiled-output', type: 'commonjs' })
    )
    rmSync(fixture.packageMarkerPath)
    symlinkSync(externalMarker, fixture.packageMarkerPath)
    expect(resolveAppImageRuntimeIdentity(fixture.identity)).toBeNull()
  })

  it('rejects inherited AppImage variables around a non-AppImage executable', () => {
    const fixture = createFixture()
    expect(
      resolveAppImageRuntimeIdentity({
        ...fixture.identity,
        execPath: join(fixture.root, 'opt', 'Orca', 'orca-ide'),
        resourcesPath: join(fixture.root, 'opt', 'Orca', 'resources')
      })
    ).toBeNull()
  })

  it('rejects a resources path outside the runtime root', () => {
    const fixture = createFixture()
    expect(
      resolveAppImageRuntimeIdentity({
        ...fixture.identity,
        resourcesPath: `${fixture.appDirPath}-other/resources`
      })
    ).toBeNull()
  })

  it('rejects the identity off Linux', () => {
    const fixture = createFixture()
    expect(resolveAppImageRuntimeIdentity({ ...fixture.identity, platform: 'darwin' })).toBeNull()
  })
})

describe('hasAppImagePathEnvironment', () => {
