    const transcriptPath =
      provider.agent === 'grok'
        ? path.join(
            fakeGrokHome,
            'sessions',
            encodeURIComponent(coordinatorWorktreePath),
            sessionId,
            'chat_history.jsonl'
          )
        : provider.agent === 'omp'
          ? path.join(fakeOmpHome, 'workspace', `2026-08-30T00-00-00_${sessionId}.jsonl`)
          : path.join(transcriptDir, `${provider.agent}-session.jsonl`)
    const initialTranscript = provider
      .transcript(sessionId, provider.first, provider.second, provider.third)
      .split('\n')
      .filter(Boolean)
    // The initial file intentionally stops before the cursor continuation row.
    mkdirSync(path.dirname(transcriptPath), { recursive: true })
    writeFileSync(transcriptPath, `${initialTranscript.slice(0, 2).join('\n')}\n`)
    // The fake CLI reads this after receiving the injected preamble, so the hook
    // is emitted through the same authenticated path as a real provider hook.
    writeFileSync(
      path.join(fakeCliDir, `${provider.agent}-config.json`),
      JSON.stringify({
        sessionId,
        transcriptPath,
        ...(provider.agent === 'grok'
          ? { cwd: coordinatorWorktreePath, grokHome: fakeGrokHome }
          : {})
      })
    )
    const started = await client.call<{
      dispatchId: string
      effects: { kind: string; role?: string; id?: string }[]
    }>('orchestration.workerStart', {
      task: task.result.task.id,
      from: coordinatorHandle,
      agent: provider.agent,
      timeoutMs: 30_000
    })
    const workerHandle = started.result.effects.find(
      (effect) => effect.kind === 'terminal' && effect.role === 'agent'
    )?.id
    if (!workerHandle) {
      throw new Error(`${provider.agent} worker-start returned no agent terminal`)
    }
    const worker = await listWorker(client, workerHandle)

    type WorkerRead = {
      source: string
      fallbackReason?: string | null
      provider?: string
      cursor?: string
      transcript?: { messages: { blocks: { type: string; text?: string }[] }[] }
    }
    let firstRead: { result: WorkerRead } | undefined
    await expect
      .poll(
        async () => {
          try {
            firstRead = await client.call('orchestration.workerRead', {
              dispatch: started.result.dispatchId,
              source: 'auto',
              limit: 10
            })
            return `${firstRead.result.source}:${firstRead.result.fallbackReason ?? 'none'}`
          } catch {
            return ''
          }
        },
        { timeout: 30_000, message: `${provider.agent} transcript never became readable` }
      )
      .toBe('transcript:none')
    expect(firstRead?.result.provider).toBe(provider.agent)
    expect(firstRead?.result.transcript?.messages).toHaveLength(2)

    appendFileSync(transcriptPath, `${initialTranscript[2]}\n`)
    const continuation = await client.call<{
      source: string
      transcript: { messages: { blocks: { text?: string }[] }[] }
    }>('orchestration.workerRead', {
      dispatch: started.result.dispatchId,
      cursor: firstRead?.result.cursor,
      limit: 10
    })
    expect(continuation.result.source).toBe('transcript')
    expect(
      continuation.result.transcript.messages.map((message) =>
        message.blocks.map((block) => block.text).filter(Boolean)
      )
    ).toEqual([[provider.third]])

    await expect.poll(() => readPreambleRecipients()).toContain(provider.agent)
    await client.call('orchestration.send', {
      from: worker.handle,
      subject: 'Completed',
      body: `The ${provider.agent} transcript read passed. Nothing remains.`,
      type: 'worker_done',
      payload: JSON.stringify({
        taskId: task.result.task.id,
        dispatchId: started.result.dispatchId,
        outcome: 'succeeded'
      })
    })
    await expect
      .poll(async () => {
        const dispatch = await client.call<{ dispatch: { status: string } | null }>(
          'orchestration.dispatchShow',
          { task: task.result.task.id }
        )
        return dispatch.result.dispatch?.status
      })
      .toBe('completed')

    const release = await client.call<{ state: string }>('orchestration.workerRelease', {
      dispatch: started.result.dispatchId
    })
    expect(release.result.state).toBe('released')
    const archived = await client.call<{
      source: string
      provider?: string
      archived?: boolean
      status: { liveness?: string }
      transcript: { messages: { blocks: { text?: string }[] }[] }
    }>('orchestration.workerRead', { dispatch: started.result.dispatchId, source: 'auto' })
    expect(archived.result).toMatchObject({
      source: 'transcript',
      provider: provider.agent,
      archived: true,
      status: { liveness: 'exited' }
    })
    expect(
      archived.result.transcript.messages.map((message) =>
        message.blocks.map((block) => block.text).filter(Boolean)
      )
    ).toEqual([[provider.first], [provider.second], [provider.third]])
    rmSync(transcriptDir, { recursive: true, force: true })
  }
})

// The published shapes the queued-message hook tests feed the mobile session: host answers,
// drafts, submissions and stream frames.

import type { AgentJournalSubmission } from '../../../src/shared/agent-session-journal-types'
import type {
  AgentSessionQueuedMessage,
  AgentSessionQueuePause,
  AgentSessionSubscribeEvent
} from '../../../src/shared/agent-session-wire'
import type { RpcResponse } from '../transport/types'
import type { StructuredAgentSessionHostSupport } from './mobile-structured-agent-session-host-support'

export const SESSION_ID = 'session-1'

export const CAPABLE: StructuredAgentSessionHostSupport = {
  promptCancel: false,
  questionAnswers: false,
  queuedMessages: true,
  queuedCommands: false,
  queuedMessageEdit: true,
  statusFeed: false,
  quietRepeatedStop: false,
  sendOptions: false,
  conversationStop: false,
  permissionModes: false,
  itemDetail: false,
  phoneAttachments: false
}
export const LEGACY: StructuredAgentSessionHostSupport = {
  ...CAPABLE,
  queuedMessages: false,
  queuedMessageEdit: false
}

export function ok(result: unknown): RpcResponse {
  return { id: 'request-1', ok: true, result, _meta: { runtimeId: 'runtime-1' } }
}

/** The fields one recorded request carried, read without asserting their shape. */
export function fieldsOf(value: unknown): Record<string, unknown> {
  return typeof value === 'object' && value !== null
    ? Object.fromEntries(Object.entries(value))
    : {}
}

export function mutationOk(value: unknown) {
  return ok({
    ok: true,
    replayed: false,
    fence: 3,
    cursor: { epoch: 'epoch-1', sequence: 1 },
    value
  })
}

/** A settled submission; `queuedMessageId` marks it as that draft's hand-off. */
export function acceptedSubmission(
  clientMessageId: string,
  queuedMessageId?: string
): AgentJournalSubmission {
  return {
    clientMessageId,
    ...(queuedMessageId ? { queuedMessageId } : {}),
    fence: 3,
    payloadFingerprint: 'fp',
    dispatchState: 'accepted',
    providerItemId: `item-${clientMessageId}`,
    reason: null,
    submittedAt: 10,
    resolvedAt: 11
  }
}

export function queuedDraft(
  overrides: Partial<AgentSessionQueuedMessage> & { messageId: string }
): AgentSessionQueuedMessage {
  return {
    position: 1,
    body: {
      kind: 'message',
      role: 'user',
      blocks: [{ type: 'text', text: `text of ${overrides.messageId}` }]
    },
    state: 'waiting',
    ...overrides
  }
}

export function snapshotEvent(input?: {
  queuedMessages?: AgentSessionQueuedMessage[] | null
  runningTurn?: boolean
  submissions?: AgentJournalSubmission[]
}): AgentSessionSubscribeEvent {
  return {
    type: 'snapshot',
    sessionId: SESSION_ID,
    fence: 3,
    page: {
      sessionId: SESSION_ID,
      epoch: 'epoch-1',
      fence: 3,
      direction: 'tail',
      items: input?.runningTurn
        ? [
            {
              itemId: 'turn-item-1',
              revision: 1,
              body: { kind: 'turn', turnId: 'turn-1', state: 'running' },
              sequence: 1,
              observedAt: 1
            }
          ]
        : [],
      removedItemIds: [],
      submissions: input?.submissions ?? [],
      window: { oldest: null, newest: null, nextCursor: { epoch: 'epoch-1', sequence: 0 } },
      liveCursor: { epoch: 'epoch-1', sequence: 0 },
      hasOlder: false,
      hasNewer: false
    },
    ...(input?.queuedMessages !== undefined ? { queuedMessages: input.queuedMessages } : {})
  }
}

export function batchEvent(
  queuedMessages?: AgentSessionQueuedMessage[] | null,
  submissions: AgentJournalSubmission[] = [],
  queuePause?: AgentSessionQueuePause | null
): AgentSessionSubscribeEvent {
  return {
    type: 'batch',
    sessionId: SESSION_ID,
    batch: {
      cursor: { epoch: 'epoch-1', sequence: 2 },
      items: [],
      removedItemIds: [],
      submissions
    },
    ...(queuedMessages !== undefined ? { queuedMessages } : {}),
    ...(queuePause !== undefined ? { queuePause } : {})
  }
}

