it('uses a fresh connection for each hook across fake-time advances', async () => {
  vi.useFakeTimers({
    shouldAdvanceTime: true,
    toFake: ['Date', 'performance', 'setTimeout', 'clearTimeout']
  })
  const server = new SocketTrackingHookServer()
  try {
    await server.start({ env: 'production' })
    server.trackRequestSockets()
    for (let index = 0; index < 3; index += 1) {
      const response = await postHookEvent(
        server,
        buildBody({ hook_event_name: 'UserPromptSubmit', prompt: 'fresh turn' })
      )
      expect(response.status).toBe(204)
      if (index === 1) {
        vi.advanceTimersByTime(120_000)
      }
    }
    expect(server.requestSockets.size).toBe(3)
  } finally {
    server.stop()
    vi.useRealTimers()
  }
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE } from '../../shared/browser-client-host-protocol'
import { isBrowserClientHostAuthorityReplaced } from './browser-client-host-authority-replacement'
import { BrowserClientHostAuthorityReplacementWait } from './browser-client-host-authority-replacement-wait'

function errorWithCode(message: string, code: unknown): Error {
  return Object.assign(new Error(message), { code })
}

describe('browser client host authority replacement', () => {
  it('recognizes the structured mismatch code a current runtime sends', () => {
    const rejected = errorWithCode(
      'lease attach named a retired runtime',
      BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE
    )

    expect(isBrowserClientHostAuthorityReplaced(rejected)).toBe(true)
  })

  it('recognizes the mismatch when a new client talks to a runtime older than the typed code', () => {
    // The pre-typed-code wire shape: same condition, reported as a generic error carrying the code
    // as its whole message. A false negative here destroys live guests on every restart.
    const rejected = new Error(BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE)

    expect('code' in rejected).toBe(false)
    expect(isBrowserClientHostAuthorityReplaced(rejected)).toBe(true)
  })

  it('rejects a host error that carries an unrelated code and an unrelated message', () => {
    const unrelated = errorWithCode('browser host process exited', 'runtime_error')

    expect(isBrowserClientHostAuthorityReplaced(unrelated)).toBe(false)
  })

  it('rejects non-Error rejections, including a bare object carrying the mismatch code', () => {
    expect(isBrowserClientHostAuthorityReplaced(undefined)).toBe(false)
    expect(isBrowserClientHostAuthorityReplaced(null)).toBe(false)
    expect(isBrowserClientHostAuthorityReplaced(BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE)).toBe(
      false
    )
    expect(
      isBrowserClientHostAuthorityReplaced({ code: BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE })
    ).toBe(false)
  })

  it('rejects a non-string code that a loose comparison could coerce', () => {
    expect(isBrowserClientHostAuthorityReplaced(errorWithCode('host rejected attach', 503))).toBe(
      false
    )
    expect(
      isBrowserClientHostAuthorityReplaced(
        errorWithCode('host rejected attach', {
          toString: () => BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE
        })
      )
    ).toBe(false)
  })

  it('rejects a message that merely contains the mismatch code inside a longer sentence', () => {
    // Substring matching was rejected deliberately: it would keep guests alive on unrelated errors
    // that happen to quote the code.
    const quoted = new Error(`failed: ${BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE} occurred`)

    expect(isBrowserClientHostAuthorityReplaced(quoted)).toBe(false)
  })

  it('pins the mismatch code string', () => {
    // Wire contract shared with the runtime: changing the value breaks mixed-version clients, whose
    // legacy message fallback compares against exactly this string.
    expect(BROWSER_CLIENT_HOST_AUTHORITY_MISMATCH_CODE).toBe(
      'browser_client_host_authority_mismatch'
    )
  })
})

describe('BrowserClientHostAuthorityReplacementWait', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('expires exactly once, at the grace deadline', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const expire = vi.fn()

    wait.arm(expire)

    expect(wait.armed).toBe(true)
    vi.advanceTimersByTime(999)
    expect(expire).not.toHaveBeenCalled()
    vi.advanceTimersByTime(1)
    expect(expire).toHaveBeenCalledOnce()
    expect(wait.armed).toBe(false)
    vi.advanceTimersByTime(10_000)
    expect(expire).toHaveBeenCalledOnce()
  })

  // A replaced runtime typically produces a burst of mismatch errors, one per in-flight attach.
  // Re-arming per error would push the deadline out indefinitely, which is the unbounded hold the
  // class exists to prevent.
  it('keeps the first deadline when armed again while already armed', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const first = vi.fn()
    const second = vi.fn()

    wait.arm(first)
    vi.advanceTimersByTime(900)
    wait.arm(second)
    vi.advanceTimersByTime(100)

    expect(first).toHaveBeenCalledOnce()
    expect(second).not.toHaveBeenCalled()
  })

  it('never expires after a cancel', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const expire = vi.fn()
    wait.arm(expire)

    wait.cancel()

    expect(wait.armed).toBe(false)
    vi.advanceTimersByTime(10_000)
    expect(expire).not.toHaveBeenCalled()
  })

  it('is re-armable after a cancel and after an expiry', () => {
    const wait = new BrowserClientHostAuthorityReplacementWait(1_000)
    const cancelled = vi.fn()
    const rearmed = vi.fn()
    wait.arm(cancelled)
    wait.cancel()

    wait.arm(rearmed)
    vi.advanceTimersByTime(1_000)

    expect(cancelled).not.toHaveBeenCalled()
    expect(rearmed).toHaveBeenCalledOnce()

    const afterExpiry = vi.fn()
    wait.arm(afterExpiry)
    vi.advanceTimersByTime(1_000)
    expect(afterExpiry).toHaveBeenCalledOnce()
  })
})

import type {
  BrowserClientHostCommandEvent,
  BrowserClientHostLeaseAuthority
} from '../../shared/browser-client-host-protocol'
import { describe, expect, it, vi } from 'vitest'
import { BrowserHostCommandLedger } from '../runtime/browser-host/browser-host-command-ledger'
import { BrowserClientHostCommandDispatcher } from './browser-client-host-command-dispatcher'

const authority: BrowserClientHostLeaseAuthority & {
  pageCommandProtocolVersion: 1
  pageReconciliationProtocolVersion: 1
} = {
  authorityRuntimeId: 'runtime-a',
  authorityEpoch: 'epoch-new',
  browserHostClientId: 'host-a',
  browserHostGeneration: 3,
  pageCommandProtocolVersion: 1,
  pageReconciliationProtocolVersion: 1
}

const previousAuthority = {
  authorityRuntimeId: 'runtime-a',
  authorityEpoch: 'epoch-old',
  browserHostClientId: 'host-a',
  browserHostGeneration: 2,
  pageHostGeneration: 7
}

function event(
  command: BrowserClientHostCommandEvent['command'],
  overrides: Partial<BrowserClientHostCommandEvent> = {}
): BrowserClientHostCommandEvent {
  return {
    type: 'command',
    ...authority,
    browserPageId: 'page-a',
    pageHostGeneration: command.type === 'closePage' ? 7 : 8,
    commandSequence: 1,
    commandId: `${command.type}-a`,
    command,
    ...overrides
  }
}

describe('browser reconciliation command ordering', () => {
  it.each([
    {
      type: 'reclaimPage' as const,
      previousAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    },
    {
      type: 'restorePage' as const,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    },
    { type: 'closePage' as const, targetAuthority: previousAuthority }
  ])('admits $type as an authenticated first client-dispatch command', async (command) => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })

    await expect(dispatcher.dispatch(event(command))).resolves.toEqual({ status: 'completed' })
    expect(handler).toHaveBeenCalledOnce()
  })

  it('deduplicates exact reclaim bootstrap and rejects changed prior authority', async () => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
    const reclaim = event({
      type: 'reclaimPage',
      previousAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    })

    const first = dispatcher.dispatch(reclaim)
    const duplicate = dispatcher.dispatch(reclaim)
    await expect(first).resolves.toEqual({ status: 'completed' })
    await expect(duplicate).resolves.toEqual({ status: 'completed' })
    expect(handler).toHaveBeenCalledOnce()
    expect(() =>
      dispatcher.dispatch({
        ...reclaim,
        command: {
          ...reclaim.command,
          previousAuthority: { ...previousAuthority, authorityEpoch: 'different' }
        }
      } as BrowserClientHostCommandEvent)
    ).toThrow('browser_host_command_sequence_conflict')
  })

  it('snapshots nested reconciliation authority on both sides of dispatch', async () => {
    const handler = vi.fn().mockResolvedValue({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
    const clientAuthority = { ...previousAuthority }
    const clientEvent = event({
      type: 'reclaimPage',
      previousAuthority: clientAuthority,
      browserProfileId: 'profile-a',
      executionHostKey: 'host-key-a'
    })

    const dispatched = dispatcher.dispatch(clientEvent)
    clientAuthority.authorityEpoch = 'mutated-client'
    await dispatched
    const accepted = handler.mock.calls[0]?.[0] as BrowserClientHostCommandEvent
    expect(accepted.command).toMatchObject({
      previousAuthority: expect.objectContaining({ authorityEpoch: 'epoch-old' })
    })
    expect(
      Object.isFrozen(accepted.command.type === 'reclaimPage' && accepted.command.previousAuthority)
    ).toBe(true)

    const delivery = vi.fn()
    const ledger = new BrowserHostCommandLedger({ authority })
    ledger.attach(delivery)
    const serverAuthority = { ...previousAuthority }
    ledger.issue({
      browserPageId: 'page-b',
      pageHostGeneration: 8,
      command: {
        type: 'reclaimPage',
        previousAuthority: serverAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      }
    })
    serverAuthority.authorityEpoch = 'mutated-server'
    const emitted = delivery.mock.calls[0]?.[0] as BrowserClientHostCommandEvent
    expect(emitted.command).toMatchObject({
      previousAuthority: expect.objectContaining({ authorityEpoch: 'epoch-old' })
    })
    expect(
      Object.isFrozen(emitted.command.type === 'reclaimPage' && emitted.command.previousAuthority)
    ).toBe(true)
  })

  it.each(['reclaimPage', 'restorePage'] as const)(
    'cancels navigation when %s bootstrap fails',
    async (type) => {
      const handler = vi
        .fn()
        .mockResolvedValueOnce({ status: 'failed', errorCode: 'bootstrap_failed' })
      const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })
      const bootstrap =
        type === 'reclaimPage'
          ? {
              type,
              previousAuthority,
              browserProfileId: 'profile-a',
              executionHostKey: 'host-key-a'
            }
          : {
              type,
              browserProfileId: 'profile-a',
              executionHostKey: 'host-key-a'
            }
      const first = dispatcher.dispatch(event(bootstrap))
      const navigate = dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: `${type}-navigate` }
        )
      )

      await expect(first).resolves.toEqual({
        status: 'failed',
        errorCode: 'bootstrap_failed'
      })
      await expect(navigate).resolves.toEqual({
        status: 'failed',
        errorCode: 'browser_host_command_dependency_failed'
      })
      expect(handler).toHaveBeenCalledOnce()
    }
  )

  it('makes an exact close terminal while allowing navigate after reclaim', async () => {
    const dispatcher = new BrowserClientHostCommandDispatcher({
      authority,
      handler: vi.fn().mockResolvedValue({ status: 'completed' })
    })
    await dispatcher.dispatch(
      event({
        type: 'reclaimPage',
        previousAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      })
    )
    await expect(
      dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-a' }
        )
      )
    ).resolves.toEqual({ status: 'completed' })

    const closing = new BrowserClientHostCommandDispatcher({
      authority,
      handler: vi.fn().mockResolvedValue({ status: 'completed' })
    })
    await closing.dispatch(event({ type: 'closePage', targetAuthority: previousAuthority }))
    expect(() =>
      closing.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-after-close', pageHostGeneration: 7 }
        )
      )
    ).toThrow('browser_host_page_generation_stale')
  })

  it('allows the same generation to continue after a failed close', async () => {
    const handler = vi
      .fn()
      .mockResolvedValueOnce({ status: 'failed', errorCode: 'authority_stale' })
      .mockResolvedValueOnce({ status: 'completed' })
    const dispatcher = new BrowserClientHostCommandDispatcher({ authority, handler })

    await expect(
      dispatcher.dispatch(event({ type: 'closePage', targetAuthority: previousAuthority }))
    ).resolves.toEqual({ status: 'failed', errorCode: 'authority_stale' })
    await expect(
      dispatcher.dispatch(
        event(
          { type: 'navigate', url: 'https://remote.internal/' },
          { commandSequence: 2, commandId: 'navigate-after-failed-close', pageHostGeneration: 7 }
        )
      )
    ).resolves.toEqual({ status: 'completed' })
  })

  it('issues reconciliation bootstrap commands from the server ledger without create', () => {
    const delivery = vi.fn()
    const ledger = new BrowserHostCommandLedger({ authority })
    ledger.attach(delivery)

    const reclaim = ledger.issue({
      browserPageId: 'page-a',
      pageHostGeneration: 8,
      command: {
        type: 'reclaimPage',
        previousAuthority,
        browserProfileId: 'profile-a',
        executionHostKey: 'host-key-a'
      }
    })
    const navigate = ledger.issue({
      browserPageId: 'page-a',
      pageHostGeneration: 8,
      command: { type: 'navigate', url: 'https://remote.internal/' }
    })
    const close = ledger.issue({
      browserPageId: 'page-b',
      pageHostGeneration: 9,
      resultAdmission: 'reconciliation',
      command: {
        type: 'closePage',
        targetAuthority: { ...previousAuthority, pageHostGeneration: 9 }
      }
    })

    expect(reclaim.event.commandSequence).toBe(1)
    expect(navigate.event.commandSequence).toBe(2)
    expect(close.event.commandSequence).toBe(1)
    expect(delivery).toHaveBeenCalledTimes(3)
    expect(() =>
      ledger.issue({
        browserPageId: 'page-b',
        pageHostGeneration: 9,
        command: { type: 'navigate', url: 'https://after-close.invalid/' }
      })
    ).toThrow('browser_host_command_page_terminal')
  })
})

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { createCommand, createHarness } from './browser-client-page-command-executor-test-harness'

describe('BrowserClientPageCommandExecutor authority fencing', () => {
  beforeEach(() => vi.restoreAllMocks())

  it('does not retain a page when close races its in-flight creation', async () => {
    const { dependencies, executor, order, route } = createHarness()
    let resolveRoute = (_route: typeof route): void => {}
    dependencies.retainNetworkRoute.mockImplementationOnce(
      () =>
        new Promise((resolve) => {
          resolveRoute = resolve
        })
    )
    const creating = executor.handle(createCommand('createPage'), new AbortController().signal)
    await Promise.resolve()

    await expect(executor.close()).rejects.toThrow('Browser client page executor cleanup failed')
    resolveRoute(route)

    await expect(creating).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    expect(executor.hasPage('page-a', 7)).toBe(false)
    expect(order).toEqual(['release-route'])
  })

  it('retires every retained page before fencing later commands', async () => {
    const { executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    await executor.close()

    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
  })

  it('revokes retained navigation once without inferring guest destruction', async () => {
    const { dependencies, executor, order, route } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    executor.fenceNavigation()
    executor.fenceNavigation()

    expect(dependencies.routeWebContents.revokeNavigation).toHaveBeenCalledOnce()
    expect(order.at(-1)).toBe('revoke-navigation')
    expect(route.release).not.toHaveBeenCalled()
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    await executor.close()
  })

  it('retains inventory while fencing old pages and uses the replacement route identity', async () => {
    const { dependencies, executor } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)

    executor.beginAuthorityTransition()

    expect(executor.snapshotPageInventory()).toEqual([
      expect.objectContaining({ browserPageId: 'page-a', authorityRuntimeId: 'runtime-a' })
    ])
    expect(dependencies.routeWebContents.revokeNavigation).toHaveBeenCalledOnce()
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })

    executor.completeAuthorityTransition({
      authorityConnectionIdentity: 'authority-record-b',
      legacyAuthorityConnectionIdentity: 'legacy-authority-record-b'
    })
    await expect(
      executor.handle(
        createCommand('navigate', {
          authorityRuntimeId: 'runtime-b',
          authorityEpoch: 'epoch-b',
          browserHostGeneration: 1
        }),
        new AbortController().signal
      )
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_generation_stale'
    })
    expect(dependencies.routeWebContents.navigateGuest).not.toHaveBeenCalled()

    await executor.retirePage('page-a', 7)
    await executor.handle(
      createCommand('createPage', {
        authorityRuntimeId: 'runtime-b',
        authorityEpoch: 'epoch-b',
        browserPageId: 'page-b',
        pageHostGeneration: 1
      }),
      new AbortController().signal
    )

    expect(dependencies.routeSessions.preparePage).toHaveBeenLastCalledWith(
      expect.objectContaining({
        identity: expect.objectContaining({ authorityConnectionIdentity: 'authority-record-b' })
      })
    )
  })

  it('releases an in-flight old-authority create during transition', async () => {
    const { dependencies, executor, order, route } = createHarness()
    let resolveRoute = (_route: typeof route): void => {}
    dependencies.retainNetworkRoute.mockImplementationOnce(
      () =>
        new Promise((resolve) => {
          resolveRoute = resolve
        })
    )
    const creating = executor.handle(createCommand('createPage'), new AbortController().signal)
    await Promise.resolve()

    executor.beginAuthorityTransition()
    resolveRoute(route)

    await expect(creating).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
    expect(executor.snapshotPageInventory()).toEqual([])
    expect(dependencies.routeWebContents.grantNavigation).not.toHaveBeenCalled()
    expect(order).toEqual(['release-route'])
    executor.completeAuthorityTransition({
      authorityConnectionIdentity: 'authority-record-b',
      legacyAuthorityConnectionIdentity: 'legacy-authority-record-b'
    })
    await executor.close()
  })

  it('keeps transition fail-closed when navigation revocation throws', async () => {
    const { dependencies, executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)
    dependencies.routeWebContents.revokeNavigation.mockImplementationOnce(() => {
      order.push('revoke-navigation')
      throw new Error('transition revocation failed')
    })

    expect(() => executor.beginAuthorityTransition()).toThrow(
      'Browser client page navigation fencing failed'
    )
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })

    await executor.close()
    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
  })

  it('continues exact page cleanup when navigation revocation throws', async () => {
    const { dependencies, executor, order } = createHarness()
    await executor.handle(createCommand('createPage'), new AbortController().signal)
    dependencies.routeWebContents.revokeNavigation.mockImplementationOnce(() => {
      order.push('revoke-navigation')
      throw new Error('navigation revocation failed')
    })

    await expect(executor.close()).rejects.toMatchObject({
      message: 'Browser client page navigation fencing failed',
      errors: [expect.objectContaining({ message: 'navigation revocation failed' })]
    })

    expect(order.slice(-6)).toEqual([
      'revoke-navigation',
      'release-guest',
      'retire-guest',
      'retire-renderer-page',
      'release-session',
      'release-route'
    ])
    await expect(
      executor.handle(createCommand('navigate'), new AbortController().signal)
    ).resolves.toEqual({
      status: 'failed',
      errorCode: 'browser_client_page_executor_closed'
    })
  })
})

import { describe, expect, it } from 'vitest'
import {
  browserAuthorityExecutionHostStorageIdentity,
  browserNetworkExecutionHostStorageIdentity,
  legacyBrowserNativeExecutionHostStorageIdentity,
  legacyBrowserNetworkExecutionHostStorageIdentity
} from './browser-execution-host-storage-identity'
import { browserNetworkExecutionHostKey } from './browser-network-execution-route'

const storageKey = 'a'.repeat(64)
const otherStorageKey = 'b'.repeat(64)

describe('browserNetworkExecutionHostStorageIdentity', () => {
  it('ignores the per-boot components the route key fences on', () => {
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-a', revision: 1 },
        storageKey
      )
    ).toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-a', revision: 2 },
        storageKey
      )
    )
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 1, distro: 'Ubuntu' },
        storageKey
      )
    ).toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 2, distro: 'Ubuntu' },
        storageKey
      )
    )
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: 'ssh-1', providerEpoch: 'epoch-a', connectionGeneration: 1 },
        storageKey
      )
    ).toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: 'ssh-1', providerEpoch: 'epoch-b', connectionGeneration: 2 },
        storageKey
      )
    )
  })

  // Why: runtimeId is a per-process randomUUID, so hashing it minted a fresh partition on
  // every remote-server restart and dropped the user's cookies.
  it('survives the authority runtime restarting under a new runtimeId', () => {
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-a', revision: 1 },
        storageKey
      )
    ).toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-b', revision: 9 },
        storageKey
      )
    )
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 1, distro: 'Ubuntu' },
        storageKey
      )
    ).toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-b', revision: 9, distro: 'Ubuntu' },
        storageKey
      )
    )
  })

  it('separates every boundary that changes storage or egress', () => {
    const identities = [
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-a', revision: 1 },
        storageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'runtime-a', revision: 1 },
        otherStorageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 1, distro: 'Ubuntu' },
        storageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 1, distro: 'Debian' },
        storageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'runtime-a', revision: 1, distro: 'Ubuntu' },
        otherStorageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: 'ssh-1', providerEpoch: 'epoch-a', connectionGeneration: 1 },
        storageKey
      ),
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: 'ssh-2', providerEpoch: 'epoch-a', connectionGeneration: 1 },
        storageKey
      )
    ]

    expect(new Set(identities).size).toBe(identities.length)
  })

  it('keeps delimiter-bearing components structurally distinct', () => {
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'a', revision: 1, distro: 'b","c' },
        'a'
      )
    ).not.toBe(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'a', revision: 1, distro: 'c' },
        'a","b'
      )
    )
  })

  // Why: these strings are hashed into persisted partition names, and the pre-migration forms
  // name the jar adoption must find -- changing either relocates or strands the user's cookies.
  it('pins the storage identity of every host kind, current and pre-migration', () => {
    const tag = '"orca-browser-execution-host-storage",1'

    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'native', runtimeId: 'r', revision: 1 },
        storageKey
      )
    ).toBe(`[${tag},"authority","${storageKey}"]`)
    expect(browserAuthorityExecutionHostStorageIdentity(storageKey)).toBe(
      `[${tag},"authority","${storageKey}"]`
    )
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'wsl', runtimeId: 'r', revision: 1, distro: 'Ubuntu' },
        storageKey
      )
    ).toBe(`[${tag},"authority-wsl","${storageKey}","Ubuntu"]`)
    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: 'ssh-1', providerEpoch: 'e', connectionGeneration: 1 },
        storageKey
      )
    ).toBe(`[${tag},"ssh","ssh-1"]`)

    expect(legacyBrowserNativeExecutionHostStorageIdentity('r')).toBe(`[${tag},"native","r"]`)
    expect(
      legacyBrowserNetworkExecutionHostStorageIdentity({
        kind: 'native',
        runtimeId: 'r',
        revision: 1
      })
    ).toBe(`[${tag},"native","r"]`)
    expect(
      legacyBrowserNetworkExecutionHostStorageIdentity({
        kind: 'wsl',
        runtimeId: 'r',
        revision: 1,
        distro: 'Ubuntu'
      })
    ).toBe(`[${tag},"wsl","r","Ubuntu"]`)
    expect(
      legacyBrowserNetworkExecutionHostStorageIdentity({
        kind: 'ssh',
        targetId: 'ssh-1',
        providerEpoch: 'e',
        connectionGeneration: 1
      })
    ).toBe(`[${tag},"ssh","ssh-1"]`)
  })

  // Why: adoption trusts the pre-migration name, so distros sharing one would hand a
  // second distro the first one's logged-in jar.
  it('keeps pre-migration WSL distros apart on one runtime', () => {
    expect(
      legacyBrowserNetworkExecutionHostStorageIdentity({
        kind: 'wsl',
        runtimeId: 'r',
        revision: 1,
        distro: 'Ubuntu'
      })
    ).not.toBe(
      legacyBrowserNetworkExecutionHostStorageIdentity({
        kind: 'wsl',
        runtimeId: 'r',
        revision: 1,
        distro: 'Debian'
      })
    )
  })

  // Why: the kind tag is the only thing keeping an SSH record out of the paired server's
  // own jar when the two records happen to carry the same key.
  it('never lets an SSH target share the paired server machine identity', () => {
    const shared = 'ssh-1700000000-aaa111'

    expect(
      browserNetworkExecutionHostStorageIdentity(
        { kind: 'ssh', targetId: shared, providerEpoch: 'e', connectionGeneration: 1 },
        shared
      )
    ).not.toBe(browserAuthorityExecutionHostStorageIdentity(shared))
  })

  it('is never mistaken for a route fencing key', () => {
    const host = {
      kind: 'native',
      runtimeId: 'runtime-a',
      revision: 7
    } as const

    expect(browserNetworkExecutionHostStorageIdentity(host, storageKey)).not.toBe(
      browserNetworkExecutionHostKey(host)
    )
  })
})

import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { describe, expect, it, vi } from 'vitest'
import {
  browserHostClientIdentityPath,
  readOrCreateBrowserHostClientId
} from './browser-host-client-identity'

function profileDirectory(): string {
  return mkdtempSync(join(tmpdir(), 'orca-host-identity-'))
}

describe('browser host client identity', () => {
  it('keeps one hosting identity across relaunches of the same profile', () => {
    const directory = profileDirectory()

    const first = readOrCreateBrowserHostClientId(directory)
    const second = readOrCreateBrowserHostClientId(directory)

    // Why: a fresh id per launch is what made the server fence the lease and drop the tabs.
    expect(second).toBe(first)
    expect(first).toMatch(/^[0-9a-f-]{36}$/)
  })

  it('gives each Orca profile its own hosting identity', () => {
    expect(readOrCreateBrowserHostClientId(profileDirectory())).not.toBe(
      readOrCreateBrowserHostClientId(profileDirectory())
    )
  })

  it('persists the identity where the next launch reads it', () => {
    const directory = profileDirectory()

    const identity = readOrCreateBrowserHostClientId(directory)

    expect(JSON.parse(readFileSync(browserHostClientIdentityPath(directory), 'utf-8'))).toEqual({
      version: 1,
      browserHostClientId: identity
    })
  })

  it.each([
    ['unparseable content', 'not json at all'],
    ['a future store version', JSON.stringify({ version: 2, browserHostClientId: 'kept' })],
    ['a missing identity', JSON.stringify({ version: 1 })],
    ['a non-string identity', JSON.stringify({ version: 1, browserHostClientId: 7 })],
    ['an empty identity', JSON.stringify({ version: 1, browserHostClientId: '' })],
    [
      'an identity past the wire limit',
      JSON.stringify({ version: 1, browserHostClientId: 'x'.repeat(257) })
    ]
  ])('mints a fresh identity rather than trusting %s', (_label, contents) => {
    const directory = profileDirectory()
    writeFileSync(browserHostClientIdentityPath(directory), contents)

    const identity = readOrCreateBrowserHostClientId(directory)

    expect(identity).toMatch(/^[0-9a-f-]{36}$/)
    expect(readOrCreateBrowserHostClientId(directory)).toBe(identity)
  })

  it('still names the host when the profile cannot be written', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    // A path whose parent is a file, so the directory can never be created.
    const file = join(profileDirectory(), 'occupied')
    writeFileSync(file, 'not a directory')

    expect(readOrCreateBrowserHostClientId(join(file, 'nested'))).toMatch(/^[0-9a-f-]{36}$/)
    expect(warn).toHaveBeenCalled()
  })
})

import { createServer } from 'node:http'
import type { AddressInfo } from 'node:net'
import type { Page } from '@stablyai/playwright-test'
import { expect } from './orca-app'
import { readRestartRendererState } from './orca-restart'
import type { PairedElectronClient } from './paired-electron-client'

/**
 * Shared scaffolding for the client-hosted browser survival specs.
 *
 * Extracted rather than copied a third time: every one of these specs has to distinguish "the tab
 * came back" from "a tab came back", and each private copy of that distinction is one more place it
 * can quietly weaken into a URL match that any fresh tab satisfies.
 */
export type ClientHostedMarkerFixture = {
  close(): Promise<void>
  markerUrl: string
  /** A second page the guest reaches on its own, to tell "survived" from "survived where". */
  movedUrl: string
  origin: string
}

export async function startClientHostedMarkerFixture(
  markers: { created: string; moved: string } = { created: 'survivor', moved: 'moved-on' }
): Promise<ClientHostedMarkerFixture> {
  const server = createServer((request, response) => {
    const marker = request.url === '/moved' ? markers.moved : markers.created
    response.writeHead(200, {
      'cache-control': 'no-store',
      'content-type': 'text/html; charset=utf-8'
    })
    response.end(
      `<!doctype html><html><head><title>${marker}</title></head>` +
        `<body><h1 id="marker">${marker}</h1></body></html>`
    )
  })
  await new Promise<void>((resolve, reject) => {
    server.once('error', reject)
    server.listen(0, '127.0.0.1', () => {
      server.off('error', reject)
      resolve()
    })
  })
  const origin = `http://127.0.0.1:${(server.address() as AddressInfo).port}`
  return {
    close: () =>
      new Promise<void>((resolve, reject) => {
        server.closeAllConnections()
        server.close((error) => (error ? reject(error) : resolve()))
      }),
    markerUrl: `${origin}/survivor`,
    movedUrl: `${origin}/moved`,
    origin
  }
}

export type MirroredBrowserPage = {
  localPageId: string
  placementKind: 'client' | 'server' | null
  remotePageId: string
  url: string
  visibleTabId: string | null
  /** The browser workspace the tab strip renders as one row; its X is the product close. */
  workspaceId: string
}

export async function findPairedWorktreeId(page: Page, repoPath: string): Promise<string | null> {
  return readRestartRendererState(() =>
    page.evaluate(
      (path) =>
        window.__store
          ?.getState()
          .allWorktrees()
          .find((worktree) => worktree.path === path)?.id ?? null,
      repoPath
    )
  )
}

export async function waitForPairedWorktreeId(page: Page, repoPath: string): Promise<string> {
  await expect
    .poll(() => findPairedWorktreeId(page, repoPath), {
      timeout: 120_000,
      message: 'paired client never received the host worktree'
    })
    .not.toBeNull()
  const worktreeId = await findPairedWorktreeId(page, repoPath)
  if (!worktreeId) {
    throw new Error('Paired worktree disappeared after discovery')
  }
  return worktreeId
}

export async function selectPairedWorktreeGroup(
  page: Page,
  environmentId: string,
  worktreeId: string
): Promise<void> {
  await expect
    .poll(
      () =>
        readRestartRendererState(() =>
          page.evaluate(
            ({ environmentId, worktreeId }) => {
              const state = window.__store?.getState()
              state?.setActiveWorktree(worktreeId, `runtime:${environmentId}`)
              return state?.activeGroupIdByWorktree[worktreeId] ?? null
            },
            { environmentId, worktreeId }
          )
        ),
      { timeout: 120_000, message: 'paired client never activated a tab group for the worktree' }
    )
    .not.toBeNull()
}

export async function findMirroredBrowserPage(
  page: Page,
  worktreeId: string,
  url: string
): Promise<MirroredBrowserPage | null> {
  return readRestartRendererState(() =>
    page.evaluate(
      ({ url, worktreeId }) => {
        const state = window.__store?.getState()
        for (const workspace of state?.browserTabsByWorktree[worktreeId] ?? []) {
          for (const browserPage of state?.browserPagesByWorkspace[workspace.id] ?? []) {
            if (!browserPage.url.startsWith(url)) {
              continue
            }
            const handle = state?.remoteBrowserPageHandlesByPageId[browserPage.id]
            const visibleTab = (state?.unifiedTabsByWorktree[worktreeId] ?? []).find(
              (tab) => tab.contentType === 'browser' && tab.entityId === workspace.id
            )
            return {
              localPageId: browserPage.id,
              placementKind: handle?.placement?.kind ?? null,
              remotePageId: handle?.remotePageId ?? browserPage.id,
              url: browserPage.url,
              visibleTabId: visibleTab?.id ?? null,
              workspaceId: workspace.id
            }
          }
        }
        return null
      },
      { url, worktreeId }
    )
  )
}

/** Every browser row the client holds for a worktree, for diagnosing duplicates and culls. */
export async function readClientBrowserRows(
  page: Page,
  worktreeId: string
): Promise<{ pageId: string; placementKind: string | null; url: string }[]> {
  return (
    (await readRestartRendererState(() =>
      page.evaluate((worktreeId) => {
        const state = window.__store?.getState()
        const rows: { pageId: string; placementKind: string | null; url: string }[] = []
        for (const workspace of state?.browserTabsByWorktree[worktreeId] ?? []) {
          for (const browserPage of state?.browserPagesByWorkspace[workspace.id] ?? []) {
            rows.push({
              pageId: browserPage.id,
              placementKind:
                state?.remoteBrowserPageHandlesByPageId[browserPage.id]?.placement?.kind ?? null,
              url: browserPage.url
            })
          }
        }
        return rows
      }, worktreeId)
    )) ?? []
  )
}

export async function openClientHostedFixturePage(
  client: PairedElectronClient,
  worktreeId: string,
  url: string
): Promise<MirroredBrowserPage> {
  await client.page.evaluate(async (url) => {
    const state = window.__store?.getState()
    if (!state?.activeWorktreeId) {
      throw new Error('Paired client has no active worktree')
    }
    const groupId = state.activeGroupIdByWorktree[state.activeWorktreeId]
    if (!groupId) {
      throw new Error('Paired client has no active tab group')
    }
    state.setBrowserDefaultUrl(url)
    await state.openNewBrowserTabInActiveWorkspace(groupId)
  }, url)
  await expect
    .poll(() => findMirroredBrowserPage(client.page, worktreeId, url), {
      timeout: 60_000,
      message: `paired client never materialized ${url}`
    })
    .not.toBeNull()
  const mirrored = await findMirroredBrowserPage(client.page, worktreeId, url)
  if (!mirrored) {
    throw new Error(`Mirrored browser page disappeared for ${url}`)
  }
  expect(mirrored.placementKind, 'fixture page must be hosted on the viewing desktop').toBe(
    'client'
  )
  await focusClientBrowserRow(client.page, worktreeId, mirrored.localPageId)
  return mirrored
}

/** Navigates the guest itself, the way following a link does — no client-side URL entry involved. */
export async function navigateGuest(page: Page, fromUrl: string, toUrl: string): Promise<void> {
  const navigated = await page.evaluate(
    async ({ fromUrl, toUrl }) => {
      for (const candidate of document.querySelectorAll('webview')) {
        const webview = candidate as Electron.WebviewTag
        try {
          if (!webview.getURL().startsWith(fromUrl)) {
            continue
          }
          await webview.loadURL(toUrl)
          return true
        } catch {
          // The guest may still be attaching.
        }
      }
      return false
    },
    { fromUrl, toUrl }
  )
  if (!navigated) {
    throw new Error(`No client-hosted guest was showing ${fromUrl} to navigate`)
  }
}

/**
 * Reads the marker out of the guest belonging to one specific page.
 *
 * Bound to that page's retained host rather than scanning every `<webview>`: a scan by URL alone is
 * satisfied by any guest on the fixture origin, so a run that lost the surviving tab and opened a
 * fresh one would still read the moved marker and pass.
 */
export async function readClientWebviewMarker(
  page: Page,
  target: { urlPrefix: string; remotePageId: string }
): Promise<string | null> {
  return readRestartRendererState(() =>
    page.evaluate(async ({ urlPrefix, remotePageId }) => {
      const host = document.querySelector(
        `[data-browser-client-page-id="${CSS.escape(remotePageId)}"]`
      )
      for (const candidate of host?.querySelectorAll('webview') ?? []) {
        const webview = candidate as Electron.WebviewTag
        try {
          if (!webview.getURL().startsWith(urlPrefix)) {
            continue
          }
          return (await webview.executeJavaScript(
            'document.querySelector("#marker")?.textContent ?? null'
          )) as string | null
        } catch {
          // The guest may still be attaching.
        }
      }
      return null
    }, target)
  )
}

export async function waitForRenderedClientWebview(
  page: Page,
  target: { urlPrefix: string; remotePageId: string },
  message: string
): Promise<string> {
  await expect
    .poll(() => readClientWebviewMarker(page, target), { timeout: 120_000, message })
    .not.toBeNull()
  const marker = await readClientWebviewMarker(page, target)
  if (!marker) {
    throw new Error(`Client-hosted guest for ${target.urlPrefix} lost its marker`)
  }
  return marker
}

/** Surfaces a row's pane so its guest is mounted where the scoped marker read can see it. */
export async function focusClientBrowserRow(
  page: Page,
  worktreeId: string,
  localPageId: string
): Promise<void> {
  await page.evaluate(
    ({ browserPageId, worktreeId }) => {
      window.__store?.getState().focusBrowserTabInWorktree(worktreeId, browserPageId, {
        surfacePane: true
      })
    },
    { browserPageId: localPageId, worktreeId }
  )
}

import { describe, expect, it } from 'vitest'
import type { Page } from '@stablyai/playwright-test'
import type { PairedElectronClient } from './paired-electron-client'
import {
  findMirroredBrowserPage,
  findPairedWorktreeId,
  readClientWebviewMarker
} from './client-hosted-browser-fixture'
import { readRelaunchedRuntimeId } from './client-hosted-runtime-relaunch'

function pageWhoseEvaluateThrows(message: string): Page {
  return {
    evaluate: async () => {
      throw new Error(message)
    }
  } as unknown as Page
}

function clientWhoseEvaluateThrows(message: string): PairedElectronClient {
  return {
    environmentId: 'env-1',
    page: pageWhoseEvaluateThrows(message)
  } as unknown as PairedElectronClient
}

function clientWhoseEvaluateReturns(value: string | null): PairedElectronClient {
  return {
    environmentId: 'env-1',
    page: {
      evaluate: async () => value
    }
  } as unknown as PairedElectronClient
}

describe('client-hosted restart evaluate polling', () => {
  it('treats a destroyed renderer context as a pending poll miss', async () => {
    const page = pageWhoseEvaluateThrows(
      'Execution context was destroyed, most likely because of a navigation.'
    )

    await expect(findPairedWorktreeId(page, '/repo')).resolves.toBeNull()
    await expect(findMirroredBrowserPage(page, 'wt-1', 'http://127.0.0.1/')).resolves.toBeNull()
    await expect(
      readClientWebviewMarker(page, { urlPrefix: 'http://127.0.0.1/', remotePageId: 'page-1' })
    ).resolves.toBeNull()
  })

  it('does not hide unrelated evaluate failures', async () => {
    const page = pageWhoseEvaluateThrows('fetchWorktrees failed')

    await expect(findPairedWorktreeId(page, '/repo')).rejects.toThrow('fetchWorktrees failed')
    await expect(findMirroredBrowserPage(page, 'wt-1', 'http://127.0.0.1/')).rejects.toThrow(
      'fetchWorktrees failed'
    )
    await expect(
      readClientWebviewMarker(page, { urlPrefix: 'http://127.0.0.1/', remotePageId: 'page-1' })
    ).rejects.toThrow('fetchWorktrees failed')
  })
})

describe('client-hosted relaunch wait', () => {
  it('treats a destroyed renderer context as a pending relaunch miss', async () => {
    const pending = await readRelaunchedRuntimeId(
      clientWhoseEvaluateThrows(
        'Execution context was destroyed, most likely because of a navigation.'
      ),
      'runtime-old'
    )
    expect(pending).toBeNull()
  })

  it('does not hide unrelated evaluate failures', async () => {
    await expect(
      readRelaunchedRuntimeId(clientWhoseEvaluateThrows('fetchWorktrees failed'), 'runtime-old')
    ).rejects.toThrow('fetchWorktrees failed')
  })

  it('succeeds only with a live runtime id that is not the pre-restart process', async () => {
    await expect(
      readRelaunchedRuntimeId(clientWhoseEvaluateReturns('runtime-old'), 'runtime-old')
    ).resolves.toBeNull()
    await expect(
      readRelaunchedRuntimeId(clientWhoseEvaluateReturns(null), 'runtime-old')
    ).resolves.toBeNull()
    await expect(
      readRelaunchedRuntimeId(clientWhoseEvaluateReturns('runtime-new'), 'runtime-old')
    ).resolves.toBe('runtime-new')
  })
})

import { describe, expect, it } from 'vitest'
import { OrchestrationDb } from './db'
import { createRootDispatch } from './db/root-dispatch-test-fixture'

// Why: runtime-agent-orchestration-projection skips its per-terminal dispatch
// fan-out on every 16ms graph publish while hasAnyDispatchContexts() is false,
// so the cached predicate must flip exactly when dispatch rows appear and go.
describe('orchestration empty-dispatch short-circuit (benchmark)', () => {
  it('predicate lifecycle: false when empty, true after dispatch (even completed), false after reset', () => {
    const db = new OrchestrationDb(':memory:')
    expect(db.hasAnyDispatchContexts()).toBe(false)
    const ctx = createRootDispatch(
      db,
      db.createTask({ runId: 'run_legacy_local', spec: 'work' }).id,
      'term_worker'
    )
    expect(db.hasAnyDispatchContexts()).toBe(true)
    // Completed rows still count — recent-completed lookups must stay valid.
    db.completeDispatch(ctx.id)
    expect(db.hasAnyDispatchContexts()).toBe(true)
    db.resetTasks()
    expect(db.hasAnyDispatchContexts()).toBe(false)
  })
})

